<script setup>import {ref} from 'vue';import AppShell from '../../components/AppShell.vue';import StatusPill from '../../components/StatusPill.vue';import {rfqs} from '../../api/mock';const selected=ref(rfqs[0]),quoted=ref(false);function submit(){quoted.value=true;selected.value={...selected.value,status:'已报价'}}</script>
<template><AppShell mode="portal"><div class="page-head"><div><span class="breadcrumb">供应商门户 / 询报价</span><h1>询报价工作台</h1><p>查看采购需求、澄清问题并提交有版本记录的正式报价。</p></div></div><div class="rfq-layout"><section class="panel rfq-list"><div class="toolbar slim"><div class="tabs"><button class="active">待报价 <em>3</em></button><button>已提交 <em>8</em></button><button>已结束 <em>16</em></button></div></div><button v-for="r in rfqs.slice(0,3)" :key="r.no" class="rfq-card" :class="{active:selected.no===r.no}" @click="selected=r;quoted=false"><div><span>{{r.no}}</span><StatusPill :text="r.status"/></div><b>{{r.title}}</b><p>{{r.category}} · {{r.owner}}</p><small>截止 {{r.deadline}}</small></button></section><section class="panel quote-detail"><div class="detail-head"><div><span>{{selected.no}}</span><h2>{{selected.title}}</h2><p>{{selected.category}} · 采购负责人 {{selected.owner}}</p></div><StatusPill :text="selected.status"/></div><div class="requirement"><div><span>预计采购金额</span><b>{{selected.budget}}</b></div><div><span>报价截止</span><b>{{selected.deadline}}</b></div><div><span>币种 / 税率</span><b>CNY / 13%</b></div><div><span>交付地点</span><b>上海 · 松江</b></div></div><div class="quote-section"><div class="section-title"><h3>报价明细</h3><span>共 3 项物料</span></div><table><thead><tr><th>物料与规格</th><th>需求数量</th><th>未税单价</th><th>交付周期</th></tr></thead><tbody><tr><td><b>M12-A 编码防水连接器</b><small>IP67 · 4Pin · 镀金端子</small></td><td>1,200 件</td><td><input value="46.80"/></td><td><input value="18 天"/></td></tr><tr><td><b>M12-D 编码屏蔽连接器</b><small>IP67 · 4Pin · 屏蔽壳体</small></td><td>800 件</td><td><input value="62.50"/></td><td><input value="21 天"/></td></tr><tr><td><b>现场装配插头</b><small>直头 · 螺钉接线</small></td><td>400 件</td><td><input value="38.20"/></td><td><input value="14 天"/></td></tr></tbody></table></div><div class="quote-summary"><label>报价说明<textarea>以上报价含包装及送货费用，报价有效期 30 天。</textarea></label><div><span>未税合计</span><b>¥ 121,400.00</b><span>含税合计</span><strong>¥ 137,182.00</strong><button class="primary" @click="submit">{{quoted?'报价已提交':'提交正式报价'}}</button></div></div></section></div></AppShell></template>
